namespace LivingTable.Chess
{
 public sealed partial class ChessTable:MonoBehaviour
 {
  public ChessMatch Match {get;private set;}public bool Physical {get;private set;}public bool TwoPlayers {get;private set;}public int HumanSide {get;private set;}=1;
  public bool Paused {get;private set;}public bool ManualFallback {get;private set;}public int Promotion {get;private set;}=5;public int Version {get;private set;}public bool Aligned {get;private set;}
  public ChessMove? PendingAi {get;private set;}public float Size {get;private set;}=.56f;public bool Playing=>Match!=null;public bool GameOver=>Playing&&!string.IsNullOrEmpty(Match.Result);public bool Recovering {get;private set;}public int VisiblePieceCount=>figures.Count(f=>f!=null&&f.gameObject.activeInHierarchy);public Vector3 PieceWorldPosition(int s)=>figures[s].position;public bool Busy {get;private set;}public double LastHandAt {get;private set;}
  public string Message {get;private set;}="Choose your table. White moves first.";public ChessPhysicalVision Vision {get;private set;}
  public bool HandsClear=>Time.realtimeSinceStartupAsDouble-LastHandAt>.6;
  bool desktop,buttonBusy,relocating,previousPause;int selected=-1,alignStage;Vector3 firstCorner;float nextAi;Transform board,men,ui,marks;TextMesh status;TableFacingPanel panel;
  readonly List<Material> materials=new List<Material>();readonly List<Mesh> meshes=new List<Mesh>();readonly List<Button> buttons=new List<Button>();readonly Dictionary<int,bool> armed=new Dictionary<int,bool>();
  readonly Transform[] figures=new Transform[64];Task<ChessMove> ai;int aiVersion;ChessPosition aiPosition;Material ivory,ebony,gold,green,blue,ghostWhite,ghostBlack;int grabHand=int.MinValue,grabSquare;float grabSeen;Vector3 gripLocal;bool releasingGrab;ChessPieceAudio sounds;public Vector3 HeldGripWorld=>grabHand!=int.MinValue&&figures[grabSquare]!=null?figures[grabSquare].TransformPoint(gripLocal):Vector3.zero;
  sealed class Button{public Transform root;public TableButtonVisual visual;public float radius;public Action action;}
  public void Initialize(bool preview){desktop=preview;ivory=Mat(new Color(.94f,.89f,.72f));ebony=Mat(new Color(.08f,.10f,.14f));gold=Mat(new Color(.7f,.48f,.15f));green=Mat(new Color(.13f,1,.48f),true);blue=Mat(new Color(.10f,.65f,1),true);ghostWhite=new Material(Resources.Load<Shader>("ChessAlignmentGhost"));ghostWhite.color=new Color(.25f,.9f,1,.22f);materials.Add(ghostWhite);ghostBlack=new Material(ghostWhite);ghostBlack.color=new Color(1,.55f,.12f,.22f);materials.Add(ghostBlack);sounds=Node("Chess piece sounds").gameObject.AddComponent<ChessPieceAudio>();Vision=gameObject.AddComponent<ChessPhysicalVision>();Vision.Initialize(this);companion=gameObject.AddComponent<ChessCompanion>();calibration=gameObject.AddComponent<ChessCameraCalibration>();calibration.Initialize(this);RefreshSaved();DrawScene();}
  Material Mat(Color c,bool glow=false){var m=new Material(Resources.Load<Shader>(glow?"CandyMagicGlow":"CandyPiecePlastic"));m.color=c;materials.Add(m);return m;}
  Transform Node(string name){var go=new GameObject(name);go.transform.SetParent(transform,false);return go.transform;}
  Transform Shape(Transform parent,string name,PrimitiveType shape,Vector3 p,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(shape);g.name=name;Destroy(g.GetComponent<Collider>());g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;return g.transform;}
  TextMesh Label(Transform parent,string value,Vector3 p,float size){var go=new GameObject(value);go.transform.SetParent(parent,false);go.transform.localPosition=p;var text=go.AddComponent<TextMesh>();text.text=value;text.fontSize=64;text.characterSize=size;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=new Color(1,.95f,.8f);return text;}
  public Vector3 SquareLocal(int square){float side=HumanSide;return new Vector3((square%8-3.5f)*Size/8*side,.009f,(square/8-3.5f)*Size/8*side);}
  public Vector3 SquareWorld(int square)=>transform.TransformPoint(SquareLocal(square));
  public void Configure(bool physical,bool twoPlayers,int humanSide){if(Playing)return;bool alreadyPhysical=Physical;Physical=physical;TwoPlayers=twoPlayers;HumanSide=humanSide;Aligned=!physical||(alreadyPhysical&&Aligned);Vision.ResetBoard();DrawScene();}
  public void StartGame(){if(relocating||Playing||StorageBlocked||editing||alignStage>0||calibrationBusy)return;if(Physical&&!Aligned){Message="Scan with ALIGN BOARD or adjust the attached handles, then accept the fit.";return;}Version++;Recovering=Physical&&Vision.RequiresIdentity;Match=new ChessMatch();SessionId=GameSessionStore.NewId();Unverified=imported=StorageBlocked=false;PendingAi=null;selected=-1;Paused=false;Busy=false;ManualFallback=false;Message=Physical?"Standard starting position. Keep hands clear while camera settles.":"Select a piece, then a glowing destination.";Vision.ResetBoard();SaveSession("started");DrawScene();nextAi=Time.unscaledTime+.8f;}
  public void PlayAgain(){if(!GameOver||Busy||StorageBlocked)return;NewGame();if(!Playing&&!StorageBlocked)StartGame();}
  public void NewGame(){calibration?.Cancel();calibrationBusy=false;companionRequest++;companion?.Cancel();companionOpen=false;if(!SaveSession("saved to menu"))return;SessionId=null;alignStage=0;editing=false;sessionMenu=false;RefreshSaved();Version++;StopAllCoroutines();Busy=buttonBusy=false;grabHand=int.MinValue;Match=null;Recovering=false;PendingAi=null;Paused=false;selected=-1;Vision.ResetBoard();Message="Choose your table. White moves first.";DrawScene();}
  void DrawScene(){if(board!=null){board.gameObject.SetActive(false);Destroy(board.gameObject);}board=Node("Chess board");if(!Physical){board.gameObject.AddComponent<TableCabinetVisual>().Board(Size,Size,false);for(int s=0;s<64;s++)Shape(board,ChessMove.Square(s),PrimitiveType.Cube,SquareLocal(s)-Vector3.up*.007f,new Vector3(Size/8,.006f,Size/8),(s%8+s/8)%2==0?ebony:ivory);}for(int i=0;i<8;i++){var p=SquareLocal(i);p.z=HumanSide*(-Size*.5f-.015f);var label=Label(board,((char)('a'+i)).ToString(),p,.0015f);label.transform.localRotation=Quaternion.Euler(90,0,0);var rank=SquareLocal(i*8);rank.x=-HumanSide*(Size*.5f+.015f);var number=Label(board,(i+1).ToString(),rank,.0015f);number.transform.localRotation=Quaternion.Euler(90,0,0);}DrawBoardHandles();DrawAlignmentGuide();DrawMen();DrawUI();Highlights();}
  void DrawMen(){if(men!=null){men.gameObject.SetActive(false);Destroy(men.gameObject);}foreach(var mesh in meshes)Destroy(mesh);meshes.Clear();men=Node("Chess pieces");Array.Clear(figures,0,figures.Length);var position=editing?importPosition:Match?.Position??ChessPosition.Initial();if(Physical&&!Recovering&&!editing&&Playing&&alignStage==0)return;for(int s=0;s<64;s++)if(position.Board[s]!=0){var figure=ChessPieceModel.Build(men,position.Board[s],Physical?(position.Board[s]>0?ghostWhite:ghostBlack):(position.Board[s]>0?ivory:ebony),Physical?ghostWhite:gold,meshes);figure.localPosition=SquareLocal(s);figure.localScale=PieceScale(position.Board[s]);figure.localRotation*=Quaternion.Euler(0,HumanSide<0?180:0,0);figures[s]=figure;}}
  void DrawUI()=>DrawHandoffUI();
  void Add(string name,int slot,int row,Action action,Color color,bool big=false){float diameter=big?.13f:.075f;var pos=new Vector3(slot*.11f,.013f,-Size*.5f-.09f-row*.10f);var root=new GameObject(name+" button").transform;root.SetParent(ui,false);root.localPosition=pos;var text=Label(ui,name.Replace(" ","\n"),pos+Vector3.up*.01f,big?.0025f:.0015f);text.transform.localRotation=Quaternion.Euler(90,0,0);var visual=root.gameObject.AddComponent<TableButtonVisual>();visual.Build(text.transform,color,false,true,diameter,big);visual.UseGoldTrim(true);text.color=new Color(.12f,.055f,.012f);buttons.Add(new Button{root=root,visual=visual,radius=diameter*.6f,action=action});}
  public void ToggleManual(){if(StorageBlocked||Recovering)return;ManualFallback=!ManualFallback;if(ManualFallback)Unverified=true;else if(Physical&&Vision.RequiresIdentity){Recovering=true;Vision.ResetBoard();}Version++;Vision.ClearEvidence();SaveSession("manual controls changed");DrawMen();DrawUI();}
  public void TogglePause(){if(StorageBlocked)return;Paused=!Paused;Version++;CancelGrab();Vision.ClearEvidence();SaveSession("pause changed");DrawUI();}
  public void Undo(){if(!Playing||Busy||StorageBlocked)return;Unverified=true;Version++;PendingAi=null;Match.Undo(TwoPlayers?1:Match.Position.Side==HumanSide?2:1);selected=-1;Recovering=Physical;Vision.ResetBoard();DrawMen();DrawUI();Highlights();nextAi=Time.unscaledTime+1;SaveSession("undo; assisted session");Message=Physical?"Restore the physical board to the shown position, then use MANUAL if needed.":"Move taken back.";}
  public void HoverWorld(Vector3 world){PreviewAlignment(world);var p=transform.InverseTransformPoint(world);foreach(var button in buttons){var b=button.root.localPosition;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(b.x,b.z))<button.radius)button.visual.Hover();}}
  public void ObserveHand(Vector3 world){var p=transform.InverseTransformPoint(world);if(Mathf.Abs(p.x)<Size*.55f&&Mathf.Abs(p.z)<Size*.55f&&p.y>-.03f&&p.y<.20f)LastHandAt=Time.realtimeSinceStartupAsDouble;}
  public void DirectPress(int id,Vector3 world){if(relocating)return;ObserveHand(world);if(grabHand!=int.MinValue)return;HoverWorld(world);var p=transform.InverseTransformPoint(world);if(p.y>.045f)armed[id]=true;if(p.y<-.025f||p.y>.022f||!armed.TryGetValue(id,out bool ready)||!ready)return;if(TryButton(p)){armed[id]=false;}}
  bool TryButton(Vector3 p){if(buttonBusy||p.y<-.03f||p.y>.10f)return false;foreach(var b in buttons){var at=b.root.localPosition;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(at.x,at.z))<b.radius){buttonBusy=true;b.visual.Press();sounds.Play(ChessPieceAudio.Cue.Button,b.root.position);StartCoroutine(ButtonLater(b.action));return true;}}return false;}
  IEnumerator ButtonLater(Action action){yield return new WaitForSecondsRealtime(.16f);buttonBusy=false;action();}
  public void TouchWorld(Vector3 world){if(relocating)return;var p=transform.InverseTransformPoint(world);if(alignStage==1||alignStage==2){AcceptAlignmentPoint(world);return;}if(TryButton(p))return;if(Mathf.Abs(p.y)>.15f)return;SelectSquare(SquareAt(p));}
  int SquareAt(Vector3 p){int x=Mathf.FloorToInt(p.x*HumanSide/Size*8+4),y=Mathf.FloorToInt(p.z*HumanSide/Size*8+4);return x<0||x>7||y<0||y>7?-1:y*8+x;}
  public void SelectSquare(int square){if(editing&&square>=0&&square<64){importPosition.Board[square]=brush;DrawMen();return;}if(StorageBlocked)return;if(!Playing||Paused||sessionMenu||Busy||Recovering||Match.Result!=""||square<0||Physical&&!ManualFallback)return;if(PendingAi.HasValue){if(square==PendingAi.Value.To)Play(PendingAi.Value);return;}if(!TwoPlayers&&Match.Position.Side!=HumanSide)return;var moves=Match.Position.LegalMoves();var chosen=moves.Where(m=>m.From==selected&&m.To==square&&(m.Promotion==0||m.Promotion==Promotion)).ToList();if(chosen.Count==1){Play(chosen[0]);return;}selected=Math.Sign(Match.Position.Board[square])==Match.Position.Side?square:-1;Highlights();}
  public bool BeginGrab(int hand,Vector3 world){if(relocating||StorageBlocked||Physical||!Playing||Paused||sessionMenu||Busy||grabHand!=int.MinValue||Match.Result!=""||!TwoPlayers&&Match.Position.Side!=HumanSide)return false;var p=transform.InverseTransformPoint(world);int square=SquareAt(p);if(square<0||p.y<0||p.y>.10f||Math.Sign(Match.Position.Board[square])!=Match.Position.Side)return false;grabHand=hand;grabSquare=square;grabSeen=Time.unscaledTime;selected=square;var figure=figures[square];gripLocal=figure.InverseTransformPoint(world);gripLocal.x=gripLocal.z=0;gripLocal.y=Mathf.Clamp(gripLocal.y,.012f,Math.Abs(Match.Position.Board[square])==1?.046f:.065f);FollowPinch(world);sounds.Play(ChessPieceAudio.Cue.Lift,world);Highlights();return true;}
  void FollowPinch(Vector3 world){var figure=figures[grabSquare];if(figure!=null)figure.position+=world-figure.TransformPoint(gripLocal);}
  public bool UpdateGrab(int hand,Vector3 world,bool release){if(grabHand!=hand)return false;grabSeen=Time.unscaledTime;FollowPinch(world);if(!release)return true;var point=transform.InverseTransformPoint(world);int origin=grabSquare;int ply=Match.Position.Ply;grabHand=int.MinValue;releasingGrab=true;try{if(point.y>=-.03f&&point.y<=.15f)SelectSquare(SquareAt(point));}finally{releasingGrab=false;}if(Match.Position.Ply==ply){if(figures[origin]!=null)figures[origin].localPosition=SquareLocal(origin);sounds.Play(ChessPieceAudio.Cue.Return,SquareWorld(origin));}return true;}
  public void ForgetHand(int hand){if(resizeHand==hand)EndBoardResize();armed.Remove(hand);if(grabHand==hand)CancelGrab();}
  void CancelGrab(){if(grabHand!=int.MinValue&&figures[grabSquare]!=null)figures[grabSquare].localPosition=SquareLocal(grabSquare);grabHand=int.MinValue;}
  public bool ApplyCameraMove(ChessMove move,int version){if(StorageBlocked||version!=Version||!Physical||ManualFallback||Paused||sessionMenu||Busy||Recovering||!HandsClear||!Playing)return false;if(PendingAi.HasValue&&!PendingAi.Value.Equals(move))return false;if(!PendingAi.HasValue&&!TwoPlayers&&Match.Position.Side!=HumanSide)return false;return Play(move,true);}
  public bool Play(ChessMove move,bool camera=false){if(StorageBlocked||!Playing||Paused||sessionMenu||Busy||Recovering||Physical&&!Aligned||Physical&&!camera&&!ManualFallback)return false;if(PendingAi.HasValue&&!PendingAi.Value.Equals(move))return false;var figure=figures[move.From];if(!Match.Play(move))return false;Version++;PendingAi=null;selected=-1;Message=move.ToString();if(Physical&&!camera)Unverified=true;if(!Physical)Vision.ResetBoard();if(!SaveSession(camera?"camera move":"move"))return false;if(Physical){if(!camera)Vision.ResetBoard();DrawMen();Highlights();DrawUI();nextAi=Time.unscaledTime+1;}else{if(!releasingGrab)sounds.Play(ChessPieceAudio.Cue.Lift,SquareWorld(move.From));Busy=true;StartCoroutine(AnimateMove(figure,move));}return true;}
  IEnumerator AnimateMove(Transform figure,ChessMove move){var start=figure!=null?figure.localPosition:SquareLocal(move.From);var end=SquareLocal(move.To);float age=0;while(age<.4f){if(!Paused)age+=Time.deltaTime;if(figure!=null)figure.localPosition=Vector3.Lerp(start,end,Mathf.SmoothStep(0,1,age/.4f))+Vector3.up*Mathf.Sin(Mathf.Clamp01(age/.4f)*Mathf.PI)*.025f;yield return null;}Busy=false;sounds.Play(ChessPieceAudio.Cue.Place,SquareWorld(move.To));DrawMen();Highlights();DrawUI();nextAi=Time.unscaledTime+.65f;}
  void Highlights(){if(marks!=null){marks.gameObject.SetActive(false);Destroy(marks.gameObject);}marks=Node("Legal move highlights");if(!Playing)return;var squares=new HashSet<int>();if(selected>=0){squares.Add(selected);foreach(var m in Match.Position.LegalMoves().Where(m=>m.From==selected))squares.Add(m.To);}if(PendingAi.HasValue){squares.Add(PendingAi.Value.From);squares.Add(PendingAi.Value.To);}if(Match.LastMove.HasValue){squares.Add(Match.LastMove.Value.From);squares.Add(Match.LastMove.Value.To);}foreach(int s in squares){var tile=Shape(marks,ChessMove.Square(s)+" highlight",PrimitiveType.Quad,SquareLocal(s)-Vector3.up*.002f,new Vector3(Size/8*.85f,Size/8*.85f,1),s==selected?blue:green);tile.localRotation=Quaternion.Euler(90,0,0);}}
  void Update(){UpdateHandleFeedback();if(turnHeading!=null)turnHeading.text=TurnTitle;if(grabHand!=int.MinValue&&Time.unscaledTime-grabSeen>.3f)CancelGrab();if(ai!=null&&ai.IsCompleted){var task=ai;ai=null;if(task.IsFaulted){Message="AI unavailable. Restart or use two-player mode.";}else if(!StorageBlocked&&Playing&&Version==aiVersion&&Match.Position==aiPosition&&!Paused&&!sessionMenu&&!Busy&&!Recovering){if(Physical){PendingAi=task.Result;SaveSession("AI move proposed; awaiting real pieces");Message="Move the AI piece: "+PendingAi;Highlights();DrawUI();}else Play(task.Result);}}
   if(!StorageBlocked&&Playing&&!Physical&&!Paused&&!sessionMenu&&!Busy&&!Recovering&&PendingAi.HasValue)Play(PendingAi.Value);
   if(!StorageBlocked&&Playing&&!Paused&&!sessionMenu&&!Busy&&!Recovering&&Match.Result==""&&!TwoPlayers&&Match.Position.Side!=HumanSide&&!PendingAi.HasValue&&ai==null&&Time.unscaledTime>=nextAi&&(!Physical||ManualFallback||Vision.Ready)){aiVersion=Version;aiPosition=Match.Position;var copy=aiPosition.Copy();ai=Task.Run(()=>ChessAi.Choose(copy));}
   if(status!=null){string header=!Playing?"LIVING TABLE / CHESS":Match.Result!=""?Match.Result:"CHESS - "+SideName(Match.Position.Side)+" to move"+(Match.Position.InCheck(Match.Position.Side)?" - CHECK":"");string seats=Playing&&!GameOver?"\nYou: "+SideName(HumanSide)+" | "+(TwoPlayers?"Human":"AI")+": "+SideName(-HumanSide)+" | "+(Physical?"Real board":"Virtual board"):"";status.text=companionOpen?WrapStatus(companionText):WrapStatus((GameOver?"":header)+seats+"\n"+(alignStage>0?Message:TurnGuidance)+(Playing?"\n"+(Unverified?"Manual / imported history":"Session saved") :""));}
#if ENABLE_INPUT_SYSTEM
   if(desktop&&Mouse.current!=null&&Camera.main!=null){var ray=Camera.main.ScreenPointToRay(Mouse.current.position.ReadValue());var plane=new Plane(transform.up,transform.position);if(plane.Raycast(ray,out float d)){var point=ray.GetPoint(d);HoverWorld(point);if(Mouse.current.leftButton.wasPressedThisFrame)TouchWorld(point);}}
#endif
  }
  static string WrapStatus(string text){var lines=new List<string>();foreach(var paragraph in text.Split('\n')){string line="";foreach(var word in paragraph.Split(' ')){if(line.Length+word.Length+1>42){lines.Add(line);line="";}line+=(line.Length==0?"":" ")+word;}lines.Add(line);}return string.Join("\n",lines);}
  public void PrepareRoomRecovery(){EndBoardResize();calibration?.Cancel();calibrationBusy=false;alignStage=0;StopAllCoroutines();Busy=buttonBusy=false;CancelGrab();companionRequest++;companion?.Cancel();companionOpen=false;sessionMenu=false;DrawMen();Highlights();}
  public void BeginRelocation(){if(relocating)return;calibration?.Cancel();calibrationBusy=false;proposedSizes=null;alignStage=0;SaveSession("board moving");previousPause=Paused;Paused=true;relocating=true;Version++;CancelGrab();Vision.ClearEvidence();DrawScene();}
  public void EndRelocation(){if(!relocating)return;relocating=false;Paused=previousPause;if(Physical){Aligned=false;Recovering=Playing;alignStage=3;Message="Check the adjusted grid. ACCEPT BOARD confirms this fit; no game move changed.";}DrawScene();SaveSession("board relocated");}
  void OnEnable(){ApplyRoom();}
  void OnDisable(){EndBoardResize();SaveSession("hidden");Version++;CancelGrab();Vision?.ClearEvidence();}
  void OnApplicationPause(bool pause){if(pause)EndBoardResize();if(pause&&Playing){if(relocating)previousPause=true;Paused=true;Version++;CancelGrab();SaveSession("suspended");DrawUI();}}
  void OnDestroy(){foreach(var m in materials)Destroy(m);foreach(var mesh in meshes)Destroy(mesh);}
 }
